// Server-only access to the showcase data the ported docs read. The JSON
// files under src/data/ are generated by `scripts/showcase-data.mjs` (runs
// before `dev` and `build`) from the same showcase sources and generators
// shell-docs uses. They are read from disk once per server process, not
// bundled: demo-content.json alone is tens of megabytes.
//
// Types and lookups mirror shell-docs' src/lib/registry.ts.

import { readFileSync } from "node:fs";
import { join } from "node:path";

export interface Feature {
  id: string;
  name: string;
  category: string;
  description: string;
}

export interface Demo {
  id: string;
  name: string;
  description: string;
  tags: string[];
  route: string;
  animated_preview_url?: string | null;
}

export interface Integration {
  name: string;
  slug: string;
  category: string;
  language: string;
  logo?: string;
  description: string;
  partner_docs: string | null;
  repo: string;
  copilotkit_version: string;
  backend_url: string;
  deployed: boolean;
  docs_mode?: "generated" | "authored" | "hidden";
  generative_ui?: string[];
  interaction_modalities?: string[];
  a2ui_pattern?: "schema-loading" | "schema-inline" | "llm-driven" | null;
  a2ui_agent_form?: "langgraph-state-graph" | null;
  interrupt_pattern?: "native" | "promise-based" | null;
  thread_persistence_pattern?: "langgraph" | "adk-session" | null;
  agent_config_pattern?: "shared-state" | "runtime-properties" | null;
  auth_pattern?:
    | "langgraph"
    | "ag2-dependencies"
    | "microsoft-agent-framework"
    | "runtime-onrequest"
    | null;
  voice_backend_pattern?: "adk-fastapi-agent-path" | null;
  sort_order?: number;
  managed_platform?: { name: string; url: string };
  animated_preview_url?: string | null;
  starter?: {
    path: string;
    name: string;
    description?: string;
    github_url?: string;
    demo_url?: string;
    clone_command?: string;
  };
  features: string[];
  demos: Demo[];
}

export interface Registry {
  feature_registry: {
    version: string;
    categories: { id: string; name: string }[];
    features: Feature[];
  };
  integrations: Integration[];
}

export interface CatalogCell {
  id: string;
  integration: string;
  integration_name?: string;
  feature: string;
  feature_name?: string;
  status: string;
}

export interface DemoRegion {
  file: string;
  startLine: number;
  endLine: number;
  code: string;
  language: string;
}

export interface DemoFile {
  filename: string;
  language: string;
  content: string;
  highlighted?: unknown;
}

export interface DemoRecord {
  readme?: string;
  files?: DemoFile[];
  backend_files?: DemoFile[];
  regions?: Record<string, DemoRegion>;
  highlight?: string[];
}

export interface SetupContentBundle {
  version: 1;
  concepts: Record<
    string,
    { framework: string; concept: string; source: string }
  >;
}

const DATA_DIR = join(process.cwd(), "src", "data");
const cache = new Map<string, unknown>();

/** Read a generated data file once; a missing file reads as `fallback`. */
export function readData<T>(file: string, fallback: T): T {
  if (cache.has(file)) return cache.get(file) as T;
  let value: T;
  try {
    value = JSON.parse(readFileSync(join(DATA_DIR, file), "utf8")) as T;
  } catch (err) {
    console.warn(
      `[docs-mdx] src/data/${file} is missing or unreadable; run \`npm run showcase-data\`.`,
      err instanceof Error ? err.message : err,
    );
    value = fallback;
  }
  cache.set(file, value);
  return value;
}

export function getRegistry(): Registry {
  return readData<Registry>("registry.json", {
    feature_registry: { version: "0", categories: [], features: [] },
    integrations: [],
  });
}

/** The framework whose docs are served at the root (`/quickstart`). */
export const ROOT_FRAMEWORK = "built-in-agent";

/** Frameworks with docs but no showcase package (shell-docs' DOCS_ONLY_INTEGRATIONS). */
const DOCS_ONLY_INTEGRATIONS: Integration[] = [
  {
    name: "Langchain DeepAgents",
    slug: "deepagents",
    category: "popular",
    language: "python",
    description:
      "LangChain Deep Agents connected to CopilotKit chat, state, tools, and generative UI.",
    partner_docs: null,
    repo: "",
    copilotkit_version: "",
    backend_url: "",
    deployed: true,
    docs_mode: "authored",
    sort_order: 13,
    features: [],
    demos: [],
  },
];

export function getIntegrations(): Integration[] {
  const registry = getRegistry();
  const slugs = new Set(registry.integrations.map((i) => i.slug));
  return [
    ...registry.integrations,
    ...DOCS_ONLY_INTEGRATIONS.filter((i) => !slugs.has(i.slug)),
  ];
}

export function getIntegration(slug: string): Integration | undefined {
  return getIntegrations().find((i) => i.slug === slug);
}

export function getFeature(id: string): Feature | undefined {
  return getRegistry().feature_registry.features.find((f) => f.id === id);
}

const DOCS_ONLY_FRAMEWORK_MODES: Record<string, "generated" | "authored"> = {
  a2a: "generated",
  "agent-spec": "generated",
  deepagents: "authored",
};

export function getDocsMode(slug: string): "generated" | "authored" | "hidden" {
  const integration = getIntegration(slug);
  if (integration?.docs_mode) return integration.docs_mode;
  return DOCS_ONLY_FRAMEWORK_MODES[slug] ?? "generated";
}

/** The `integrations/<folder>/` that holds a framework's own docs. */
const DOCS_FOLDER_OVERRIDES: Record<string, string> = {
  "langgraph-python": "langgraph",
  "langgraph-typescript": "langgraph",
  "langgraph-fastapi": "langgraph",
  "google-adk": "adk",
  "crewai-crews": "crewai-flows",
  strands: "aws-strands",
  "strands-typescript": "aws-strands",
  "ms-agent-dotnet": "microsoft-agent-framework",
  "ms-agent-python": "microsoft-agent-framework",
  "ms-agent-harness-dotnet": "microsoft-agent-framework",
};

export function getDocsFolder(slug: string): string {
  return DOCS_FOLDER_OVERRIDES[slug] ?? slug;
}

/**
 * Which in-page `<Tabs groupId>` value opens first on a framework's URL, so
 * `/langgraph-typescript/...` opens on the TypeScript tab.
 */
const TAB_DEFAULTS_BY_SLUG: Record<string, Record<string, string>> = {
  "langgraph-python": {
    language_langgraph_agent: "Python",
    deployment_method: "LangSmith",
  },
  "langgraph-typescript": { language_langgraph_agent: "TypeScript" },
  "langgraph-fastapi": {
    language_langgraph_agent: "Python",
    deployment_method: "FastAPI",
  },
  strands: { language_strands_agent: "Python" },
  "strands-typescript": { language_strands_agent: "TypeScript" },
  "ms-agent-dotnet": { "language_microsoft-agent-framework_agent": ".NET" },
  "ms-agent-python": { "language_microsoft-agent-framework_agent": "Python" },
  "ms-agent-harness-dotnet": {
    "language_microsoft-agent-framework_agent": ".NET",
  },
};

export function getTabDefault(
  slug: string | null | undefined,
  groupId: string | undefined,
): string | undefined {
  if (!slug || !groupId) return undefined;
  return TAB_DEFAULTS_BY_SLUG[slug]?.[groupId];
}

/** `(integration, feature) → catalog cell`, e.g. to spot `unsupported` pairs. */
export function getCatalogCell(
  integration: string,
  feature: string,
): CatalogCell | undefined {
  const key = "catalog-index";
  let index = cache.get(key) as Map<string, CatalogCell> | undefined;
  if (!index) {
    const cells =
      readData<{ cells?: CatalogCell[] }>("catalog.json", {}).cells ?? [];
    index = new Map(cells.map((c) => [`${c.integration}::${c.feature}`, c]));
    cache.set(key, index);
  }
  return index.get(`${integration}::${feature}`);
}

/** A showcase cell's bundled source, keyed `<integration>::<cell>`. */
export function getDemoRecord(
  integration: string,
  cell: string,
): DemoRecord | undefined {
  return readData<{ demos: Record<string, DemoRecord> }>("demo-content.json", {
    demos: {},
  }).demos[`${integration}::${cell}`];
}

export function getSetupContent(): SetupContentBundle {
  return readData<SetupContentBundle>("setup-content.json", {
    version: 1,
    concepts: {},
  });
}

/** One `(frontend, integration, feature)` cell of the frontend catalog. */
export interface FrontendCatalogCell {
  id: string;
  frontend: string;
  integration: string;
  feature: string;
  runnable: boolean;
  demo_route?: string;
}

export function getFrontendCatalog(): FrontendCatalogCell[] {
  return readData<{ cells?: FrontendCatalogCell[] }>("frontend-catalog.json", {})
    .cells ?? [];
}

/** Per-frontend feature support, from `showcase/shared/frontend-registry`. */
export interface FrontendRegistry {
  feature_support: Record<
    string,
    Record<
      string,
      { state: string; docs?: { name: string; description: string } }
    >
  >;
}

export function getFrontendRegistry(): FrontendRegistry {
  return readData<FrontendRegistry>("frontend-registry.json", {
    feature_support: {},
  });
}

/** A named region of the canonical Angular showcase app. */
export interface AngularSourceRegion {
  file: string;
  language: string;
  content: string;
}

export function getAngularSourceRegion(
  region: string,
): AngularSourceRegion | undefined {
  return readData<{ regions?: Record<string, AngularSourceRegion> }>(
    "angular-source-content.json",
    {},
  ).regions?.[region];
}
